<div class="card"><div class="card-header"><div class="topbar u-w-full"><div><h2>Verifikasi Pembayaran</h2><div class="small">Bukti transfer dari aplikasi Android.</div></div><div class="u-spacer-260"></div><select class="input" onchange="location.href='<?= base_url('payments'); ?>'+(this.value?'?status='+this.value:'')"><option value="">Semua status</option><?php foreach(['PENDING','APPROVED','REJECTED'] as $s):?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= $s ?></option><?php endforeach;?></select></div></div><div class="card-body"><?php if($this->session->flashdata('payments_ok')):?><div class="badge u-mb-12"><?= html_escape($this->session->flashdata('payments_ok')) ?></div><?php endif;?><?php if($this->session->flashdata('payments_err')):?><div class="badge u-badge-danger u-mb-12"><?= html_escape($this->session->flashdata('payments_err')) ?></div><?php endif;?>
<?php if(!$rows):?><div class="small">Belum ada bukti pembayaran.</div><?php endif;?>
<div class="admin-grid"><?php foreach($rows as $r):?><div class="admin-card"><div class="admin-card__head"><div><b><?= html_escape($r->order_code) ?></b><div class="small"><?= html_escape($r->client_name) ?> • <?= html_escape($r->client_phone) ?></div></div><span class="badge"><?= html_escape($r->status) ?></span></div><div class="admin-card__body"><img src="<?= base_url(trim($r->proof_path,'/')) ?>" alt="Bukti pembayaran" style="width:100%;max-height:300px;object-fit:contain;border-radius:12px;background:#111"><p><b><?= rupiah($r->amount) ?></b> via <?= html_escape($r->payment_method_name) ?></p><div class="small">Tagihan: <?= rupiah($r->total) ?> • Terbayar: <?= rupiah($r->paid) ?></div><?php if($r->note):?><p><?= nl2br(html_escape($r->note)) ?></p><?php endif;?><?php if($r->admin_note):?><p class="small">Catatan admin: <?= html_escape($r->admin_note) ?></p><?php endif;?><?php if($r->status==='PENDING'):?><form method="post" action="<?= base_url('payments/approve/'.$r->id) ?>"><?= csrf_field() ?><input class="input u-w-full u-mb-12" name="admin_note" placeholder="Catatan opsional"><button class="btn btn-gold" type="submit">Terima</button></form><form method="post" action="<?= base_url('payments/reject/'.$r->id) ?>"><?= csrf_field() ?><input class="input u-w-full u-mb-12" name="admin_note" placeholder="Alasan penolakan" required><button class="btn btn-red" type="submit">Tolak</button></form><?php endif;?></div></div><?php endforeach;?></div></div></div>